ids = await orders_list_order_ids()
futs = [orders_get_order(order_id=i) for i in ids]
rows = [await f for f in futs]
t = {}
odd = []
for r in rows:
    a = r.get("amount")
    if not isinstance(a,(int,float)): odd.append([r.get("order_id"), a]); continue
    t[r.get("region")] = t.get(r.get("region"),0)+a
